Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='storegenesis', at=datetime(2026, 9, 27, 0, 0, 0), actor='assistant', title='A store is named by its genesis; a reference by a local chain name stays on its deployment', body="A store's identity is the hash of its genesis object, not where it lives or what a deployment calls it. A deployment finds a store as the mount whose objects hold that genesis, and two clones are the same store exactly when they share it. A qualified reference RefIn names a deployment's local chain, so it means something only on that deployment, and a store that another deployment or the public reads never holds one. A dependency between such stores is written as a sentence until a reference named by genesis exists.", rationale='A stored term must mean the same thing on every host that reads it, and only the genesis is the same everywhere.', supersedes=()))